const mainJson = { ...( $('Preliminary_Decisions').first().json ) };
const raw = $('Weather_Agent').first().json.output;
const weather = JSON.parse(raw);
const weatherRaw = $('Weather_API_Call').first().json;

mainJson.weather.summary = weather.summary;
mainJson.weather.state = weather.state;
mainJson.weather.precipitation_probability = weather.precipitation_probability;

// ─── Calculate Dynamic Timezone Offset ────────────────────────────────────────

const tz = mainJson.location?.timezone || 'Africa/Algiers';

function getTzOffsetStr(timeZone) {
  const date = new Date();
  const utcDate = new Date(date.toLocaleString('en-US', { timeZone: 'UTC' }));
  const tzDate = new Date(date.toLocaleString('en-US', { timeZone }));

  const diffMinutes = Math.round((tzDate - utcDate) / 60000);
  const sign = diffMinutes >= 0 ? '+' : '-';
  const hours = String(Math.floor(Math.abs(diffMinutes) / 60)).padStart(2, '0');
  const minutes = String(Math.abs(diffMinutes) % 60).padStart(2, '0');

  return `${sign}${hours}:${minutes}`;
}

const offset = getTzOffsetStr(tz);

// Helper to format Open-Meteo time (YYYY-MM-DDTHH:mm) to our strict standard
function formatMeteoTime(meteoTime) {
  // Appends ":00" for seconds, plus the dynamic offset
  return `${meteoTime}:00${offset}`;
}

// ─── Build weather insights ───────────────────────────────────────────────────

const times    = weatherRaw.hourly.time;
const temps    = weatherRaw.hourly.temperature_2m;
const humidity = weatherRaw.hourly.relative_humidity_2m;
const precip   = weatherRaw.hourly.precipitation_probability;

// Find max and min temperature
let maxTemp = { value: -Infinity, time: null };
let minTemp = { value:  Infinity, time: null };

temps.forEach((t, i) => {
  if (t > maxTemp.value) maxTemp = { value: t, time: formatMeteoTime(times[i]) };
  if (t < minTemp.value) minTemp = { value: t, time: formatMeteoTime(times[i]) };
});

// Keep only every 3 hours to reduce size (48h → 16 entries)
const hourly = times
  .map((t, i) => ({
    time:                      formatMeteoTime(t),
    temperature:               temps[i],
    humidity:                  humidity[i],
    precipitation_probability: precip[i]
  }))
  .filter((_, i) => i % 3 === 0);

mainJson.weather.insights = {
  highlights: {
    max_temperature: maxTemp,
    min_temperature: minTemp
  },
  hourly
};

return [{ json: mainJson }];
